mapper.select:
SELECT f.id, f.plate_no AS plateNo, f.identify_time AS identifyTime, f.match_scene AS matchScene, f.status, f.station_id AS stationId, s.name AS stationName, f.handle_user_id AS handleUserId, u.nickname AS handleUserName, f.handle_time AS handleTime, f.handle_progress AS handleProgress, f.ignore_reason AS ignoreReason, f.remark, f.reserve1, f.reserve2, f.creator, f.updater, f.create_time AS createTime, f.update_time AS updateTime FROM fake_plate_control f LEFT JOIN station_info s ON f.station_id = s.id AND s.deleted = 0 LEFT JOIN user_info u ON f.handle_user_id = u.id AND u.deleted = 0 WHERE f.deleted = 0
AND f.plate_no LIKE CONCAT('%', #{reqVO.plateNo}, '%')
AND f.match_scene = #{reqVO.matchScene}
AND f.status = #{reqVO.status}
AND f.station_id = #{reqVO.stationId}
AND f.handle_user_id = #{reqVO.handleUserId}
AND f.remark LIKE CONCAT('%', #{reqVO.remark}, '%')
AND f.identify_time BETWEEN #{reqVO.identifyTime[0]} AND #{reqVO.identifyTime[1]}
ORDER BY f.id DESC
